import { Dialog, Transition } from "@headlessui/react";
import { addDoc, collection, doc, setDoc } from "firebase/firestore";
import { getDownloadURL, ref, uploadBytesResumable } from "firebase/storage";
import { nanoid } from "nanoid";
import { useRouter } from "next/router";
import { Fragment, useState } from "react";
import { analyze } from "../../lib/api";
import firebase from "../../lib/firebase";

type UploadMeetingModalProps = {
  isOpen: boolean;
  setIsOpen: (isOpen: boolean) => void;
};

type FormData = {
  interviewTitle: string;
  aboutUser: string;
    learningObjectives: string;
    date: string;
  };

export default function UploadMeetingModal({
  isOpen,
  setIsOpen,
}: UploadMeetingModalProps) {
  const [file, setFile] = useState<File | null>(null);
  const [uploadState, setUploadState] = useState<
    "initial" | "uploading" | "uploaded"
  >("initial");
  const [formFields, setFormFields] = useState<FormData>({
    interviewTitle: "",
    aboutUser: "",
    learningObjectives: "",
    date: "",
  });
  const [downloadUrl, setDownloadUrl] = useState<string | null>(null);
  const router = useRouter();

  const handleChange = (e: React.FormEvent<HTMLTextAreaElement>) => {
    const { name, value } = e.currentTarget;
    setFormFields((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!file) return;
    setUploadState("uploading");

    // upload the file.
    const storageRef = ref(firebase.storage, `meetings/${file.name}`);
    const uploadTask = uploadBytesResumable(storageRef, file);

    uploadTask.on(
      "state_changed",
      (snapshot) => {
        // progress
        console.log(
          (snapshot.bytesTransferred / snapshot.totalBytes) * 100 + "%"
        );
      },
      (err) => console.log(err),
      async () => {
        // complete
        setUploadState("uploaded");

        const url = await getDownloadURL(uploadTask.snapshot.ref);
        setDownloadUrl(url);

        try {
          const docId = nanoid();
          await generateAnalysis(url, docId);
          await postEverythingToFirebase(docId);
          router.push("/view_meeting?id=" + docId);
        } catch (error) {
          console.error(error);
        }
      }
    );
  };

  const generateAnalysis = async (url: string, docId: string) => {
    const { message } = await analyze(url, docId);
    console.log(message);
    return message;
  };

  const postEverythingToFirebase = async (docId: string) => {
    const docRef = doc(firebase.db, "conversations/" + docId);
    try {
      await setDoc(docRef, {
        title: formFields.interviewTitle,
        aboutUser: formFields.aboutUser,
        learningObjectives: formFields.learningObjectives,
        date: formFields.date,
        audioUrl: downloadUrl,
      });
      await addDoc(collection(firebase.db, "analysis"), {
        docId: docId,
        message: await generateAnalysis(downloadUrl, docId),
      });
    } catch (error) {
      console.error(error);
    }
  };
}
